export interface RegistryUnit {
  id: UnitId
  kind: UnitKind
  /** Present only for a unit with a physical definition. */
  dimension?: UnitDimension
  /** The measuring convention the unit belongs to, when it has one. */
  convention?: UnitConvention
  /** The unit this dimension is measured in. */
  base?: string
  /** Base units in one of this unit, as `n` or `n/d`. */
  factor?: string
  /** Added after scaling, for scales that do not share an origin. */
  offset?: string
  /** False when the definition is itself a culinary approximation. */
  exact?: boolean
}

