export type MeasurementSystem = 'original' | 'metric' | 'us' | 'au'

/**
 * One step of a rounding ladder: the unit a converted amount is written in
 * while it stays below the ceiling, and the practical measure it is rounded
 * to. The ceiling is stated in the rung's own unit, so this policy never
 * restates a conversion factor the registry already holds.
 */
export interface LadderRung {
  unit: UnitId
  ceiling?: string
  step: string
}

